<template>
  <ContentWrap><el-form ref="queryRef" :model="query" inline class="-mb-15px"><el-form-item label="合同名称" prop="contractName"><el-input v-model="query.contractName" clearable class="!w-220px" /></el-form-item><el-form-item label="合同编号" prop="contractNo"><el-input v-model="query.contractNo" clearable class="!w-220px" /></el-form-item><el-form-item label="状态" prop="status"><el-select v-model="query.status" clearable class="!w-160px"><el-option label="履行中" :value="0"/><el-option label="已到期" :value="1"/><el-option label="已终止" :value="2"/></el-select></el-form-item><el-form-item><el-button @click="search"><Icon icon="ep:search"/>搜索</el-button><el-button @click="reset"><Icon icon="ep:refresh"/>重置</el-button><el-button type="primary" plain v-hasPermi="['yideyifeng:contract:create']" @click="openForm('create')"><Icon icon="ep:plus"/>新增</el-button></el-form-item></el-form></ContentWrap>
  <ContentWrap><el-table v-loading="loading" :data="list" stripe show-overflow-tooltip><el-table-column label="合同编号" prop="contractNo" width="150"/><el-table-column label="合同名称" prop="contractName" min-width="180"/><el-table-column label="相对方" prop="counterparty"/><el-table-column label="开始时间" prop="startDate" width="110"/><el-table-column label="结束时间" prop="endDate" width="110"/><el-table-column label="状态" width="90"><template #default="s"><el-tag :type="s.row.status===0?'success':s.row.status===1?'warning':'info'">{{['履行中','已到期','已终止'][s.row.status]}}</el-tag></template></el-table-column><el-table-column label="OA流程数" prop="oaWorkflowCount" width="90"/><el-table-column label="OA流程摘要" prop="oaWorkflowSummary" min-width="210"/><el-table-column label="下次维护" prop="nextMaintenanceDate" width="110"/><el-table-column label="操作" fixed="right" width="250"><template #default="s"><el-button link type="primary" @click="detailRef.open(s.row.id)">详情</el-button><el-button link type="primary" v-hasPermi="['yideyifeng:contract:update']" @click="openForm('update',s.row.id)">编辑</el-button><el-dropdown v-hasPermi="['yideyifeng:contract:notice']" @command="(c)=>notice(s.row.id,c)"><el-button link type="success">通知</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="SMS">短信通知</el-dropdown-item><el-dropdown-item command="OA">OA通知</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button link type="danger" v-hasPermi="['yideyifeng:contract:delete']" @click="remove(s.row.id)">删除</el-button></template></el-table-column></el-table><Pagination :total="total" v-model:page="query.pageNo" v-model:limit="query.pageSize" @pagination="load"/></ContentWrap>
  <ContractForm ref="formRef" @success="load"/><ContractDetail ref="detailRef"/>
</template>
<script setup lang="ts">
import { ContractApi,type Contract } from '@/api/yideyifeng/contract'; import ContractForm from './ContractForm.vue'; import ContractDetail from './ContractDetail.vue'
defineOptions({name:'Contract'}); const loading=ref(false);const list=ref<Contract[]>([]);const total=ref(0);const query=reactive({pageNo:1,pageSize:10,contractName:undefined,contractNo:undefined,status:undefined});const queryRef=ref();const formRef=ref();const detailRef=ref();const message=useMessage()
const load=async()=>{loading.value=true;try{const data=await ContractApi.getPage(query);list.value=data.list;total.value=data.total}finally{loading.value=false}};const search=()=>{query.pageNo=1;load()};const reset=()=>{queryRef.value.resetFields();search()};const openForm=(type:string,id?:number)=>formRef.value.open(type,id)
const remove=async(id:number)=>{try{await message.delConfirm();await ContractApi.delete(id);message.success('删除成功');load()}catch{}};const notice=async(id:number,type:'SMS'|'OA')=>{await ContractApi.sendNotice(id,type);message.success('通知记录已写入时间线')};onMounted(load)
</script>
